const crypto = require('crypto');
const request = $json;
const body = request.body ?? request;
const headers = request.headers ?? {};
const secret = $env.WEBPRO_WEBHOOK_SECRET || '';
const receivedSignature = headers['x-webpro-signature'] || headers['X-WebPro-Signature'] || '';

if (secret) {
  const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
  const expectedSignature = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
  if (receivedSignature !== expectedSignature) {
    throw new Error('Firma WebPro invalida');
  }
}

const lead = body.lead || body;
const event = body.event || 'lead.created';
const checklist = Array.isArray(lead.checklist) ? lead.checklist : [];
const phoneItem = checklist.find(item => /whatsapp/i.test(item.question || ''));
const calendarItem = checklist.find(item => /calendar/i.test(item.question || ''));
const paymentItem = checklist.find(item => /pago/i.test(item.question || ''));

return [{
  json: {
    event,
    source: body.source || 'webpro-crm',
    occurredAt: body.occurredAt || new Date().toISOString(),
    lead,
    integrations: {
      crm: {
        email: lead.email,
        plan: lead.plan,
        total: lead.total,
        status: lead.status || 'nuevo',
        sourceId: lead.id
      },
      email: {
        to: lead.email,
        adminEmail: $env.ADMIN_EMAIL || '',
        subject: `WebPro - ${lead.plan || 'Nueva solicitud'}`
      },
      whatsapp: {
        phone: phoneItem?.answer || '',
        message: `Hola, recibimos tu solicitud WebPro para el plan ${lead.plan || ''}.`
      },
      calendar: {
        email: calendarItem?.answer || '',
        bookingRequired: Boolean(calendarItem?.answer)
      },
      payment: {
        provider: paymentItem?.answer || '',
        amount: Number(lead.total || 0),
        currency: 'USD',
        reference: lead.id
      }
    }
  }
}];

const data = $json;
return [{
  json: {
    event: data.event,
    action: 'lead.created',
    crmContact: data.integrations.crm,
    emailNotification: data.integrations.email,
    whatsappNotification: data.integrations.whatsapp,
    calendarRequest: data.integrations.calendar,
    paymentRequest: data.integrations.payment,
    lead: data.lead,
    nextSteps: [
      'Crear o actualizar contacto en el CRM',
      'Enviar confirmacion por correo',
      'Enviar WhatsApp si existe telefono y consentimiento',
      'Crear enlace de agenda si corresponde',
      'Crear checkout si corresponde'
    ]
  }
}];

const data = $json;
return [{
  json: {
    event: data.event,
    action: 'lead.status_updated',
    crmUpdate: {
      sourceId: data.lead.id,
      email: data.lead.email,
      status: data.lead.status
    },
    lead: data.lead,
    nextSteps: [
      'Actualizar estado en el CRM',
      'Enviar una notificacion segun el nuevo estado',
      'Iniciar la siguiente automatizacion comercial'
    ]
  }
}];
